import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Built-In Resources and Their Modes","description":"","frontmatter":{"id":"0289186035","title":"Built-In Resources and Their Modes","state":"Approved","created":"2026-08-03T00:00:00.000Z","tags":["naming","taxonomy","schema","built-in","defaults","lifecycle"],"category":"Platform"},"headers":[],"relativePath":"adrs/0289186035/README.md","filePath":"adrs/0289186035/README.md"}'),r={name:"adrs/0289186035/README.md"};function n(s,e,d,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="built-in-resources-and-their-modes" tabindex="-1">Built-In Resources and Their Modes <a class="header-anchor" href="#built-in-resources-and-their-modes" aria-label="Permalink to &quot;Built-In Resources and Their Modes&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../8779742261/README.html">ADR#8779742261</a> establishes the actor ladder and the mutation-authority field for rows converged from deployment configuration. A sibling concept keeps appearing next to it and is easy to conflate with it: resources defined by the <strong>software release itself</strong>. Default roles, reserved permissions, sentinel rows, standard policies, template objects: present in every installation, identical everywhere, and changed only by upgrading the software.</p><p>Built-in and system-managed share a surface symptom (the API refuses some or all mutations) but differ in every property that matters:</p><table tabindex="0"><thead><tr><th></th><th>Built-in</th><th>System-managed</th></tr></thead><tbody><tr><td>Defined by</td><td>the release (code, migrations)</td><td>this deployment&#39;s configuration</td></tr><tr><td>Varies per installation</td><td>no</td><td>yes</td></tr><tr><td>Changes when</td><td>the software upgrades</td><td>the operator changes configuration</td></tr><tr><td>Example</td><td>a reserved <code>admin</code> role, a sentinel platform row</td><td>a config-declared operator service account</td></tr></tbody></table><p>Conflating them produces wrong designs in both directions: treating a built-in as system-managed invites operators to &quot;configure&quot; something the release owns; treating a system-managed row as built-in hides it from the deployment&#39;s declared state. And &quot;built-in&quot; alone is underspecified: the industry applies built-in-ness in several distinct modes, from fully immutable to merely seeded, so declaring a resource built-in without declaring its mode leaves the enforcement undefined.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Chosen option: &quot;built-in is the release&#39;s authority, documented per resource as one of six modes&quot;, because the verified industry survey shows built-in-ness is not one behavior but a spectrum, and every ambiguity encountered came from leaving the mode implicit.</p><h3 id="definition-and-place-in-the-taxonomy" tabindex="-1">Definition and place in the taxonomy <a class="header-anchor" href="#definition-and-place-in-the-taxonomy" aria-label="Permalink to &quot;Definition and place in the taxonomy&quot;">​</a></h3><p>A <strong>built-in resource</strong> is one whose defining authority is the software release: its shape and existence ship with the code, and its legitimate mutation vehicle is an upgrade. In the actor ladder, the release acts through the <code>system</code> rung&#39;s machinery (migrations, boot reconciliation), but the authority is distinct from deployment configuration: a <code>managed_by</code>-style field, where built-ins are rows at all, marks them with their own value (<code>builtin</code>) rather than overloading <code>system</code>.</p><h3 id="the-six-modes-verified-precedents-2026-08-03" tabindex="-1">The six modes (verified precedents, 2026-08-03) <a class="header-anchor" href="#the-six-modes-verified-precedents-2026-08-03" aria-label="Permalink to &quot;The six modes (verified precedents, 2026-08-03)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>Verified precedents</th></tr></thead><tbody><tr><td>1. Immutable</td><td>Exists in every installation; nothing about it can change through any surface</td><td>PostgreSQL <code>template0</code> (&quot;should never be changed after the database cluster has been initialized&quot;, &quot;normally marked <code>datallowconn = false</code> to prevent its modification&quot;); GCP predefined roles (fixed <code>ETag AA==</code>); Azure Policy <code>policyType: Static</code>; AWS managed policies (&quot;You cannot change the permissions defined in AWS managed policies&quot;); Grafana fixed roles (&quot;called &#39;fixed&#39; because you cannot change or delete fixed roles&quot;)</td></tr><tr><td>2. Editable-except-core</td><td>The row is built-in and undeletable, most properties open, specific properties locked</td><td>Okta default policies (&quot;Default policies are required, and you can&#39;t delete them&quot;; &quot;Default policies always have one default rule that you can&#39;t delete... always the last rule in the priority order&quot;); the claim that specific default-rule sub-properties are locked is plausible but UNVERIFIED against a primary source</td></tr><tr><td>3. Reconciled-on-boot</td><td>Edits are allowed but the platform converges built-ins back to the release&#39;s definition on restart, with an explicit per-object opt-out</td><td>Kubernetes default RBAC: &quot;The API server reconciles default ClusterRole and ClusterRoleBinding objects on every restart&quot;; opt-out via the <code>rbac.authorization.k8s.io/autoupdate</code> annotation set to <code>false</code>; &quot;Many of these are <code>system:</code> prefixed, which indicates that the resource is directly managed by the cluster control plane&quot;; &quot;Modifications to default <code>system:</code> ClusterRoles... are overwritten when the API server restarts&quot;</td></tr><tr><td>4. Delete-protected-but-configurable</td><td>Cannot be deleted, freely reconfigurable, never reconciled back</td><td>Grafana basic roles (&quot;You can use RBAC to modify the permissions associated with any basic role&quot;; &quot;You can&#39;t delete basic roles&quot;); WorkOS default environment role (undeletable while it holds default status; reassign first)</td></tr><tr><td>5. Seeded-but-unprotected</td><td>The release provides defaults copied at creation time; the copies are wholly owned by their owner afterward</td><td>GitHub default labels (&quot;anyone with write access to the repository can edit or delete the labels in that repository later. Adding, editing, or deleting a default label does not add, edit, or delete the label from existing repositories&quot;); PostgreSQL <code>template1</code> (&quot;If you add objects to <code>template1</code>, these objects will be copied into subsequently created user databases&quot;)</td></tr><tr><td>6. Code-constant</td><td>The built-in is not data at all: it lives in code and never materializes as a row</td><td>Reserved role/permission keys defined in source; Clerk&#39;s <code>org:sys_*</code> permission key convention</td></tr></tbody></table><h3 id="selection-guidance" tabindex="-1">Selection guidance <a class="header-anchor" href="#selection-guidance" aria-label="Permalink to &quot;Selection guidance&quot;">​</a></h3><ol><li><strong>Prefer mode 6 (code constant) whenever the built-in has no per-installation state.</strong> A row that never varies is a liability: it must be seeded, protected, and migrated. Reserved role keys and capability sets belong in code.</li><li><strong>Use mode 1 (immutable row) when relational integrity needs an anchor row</strong>: foreign keys, audit chains, or sentinel addressing. Pair the row with database-level protection (a type/kind column plus delete and immutability triggers), since a sentinel protected only by code discipline is not protected.</li><li><strong>Use mode 3 (reconciled) when built-ins must be operator-tunable yet upgrade-refreshable</strong>, and make the opt-out explicit and per-object, as Kubernetes does with <code>autoupdate</code>; silent reconciliation over operator edits is the K8s-documented footgun (&quot;modifications... are overwritten when the API server restarts&quot;).</li><li><strong>Use mode 5 (seeded) when the default is a starting point, not a contract</strong>: after copying, the rows are ordinary user data and take the normal authority value, not <code>builtin</code>.</li><li><strong>Declare the mode in the resource&#39;s documentation and, for modes 1 through 4, enforce it in the API</strong>, following the mutation-authority ADR&#39;s enforcement rule: the marker must be checked and rejected at the write path, not merely displayed.</li><li><strong>Never let &quot;default&quot; imply &quot;protected&quot;</strong>: GitHub&#39;s default labels and Okta&#39;s default rules show the industry uses &quot;default&quot; for both protected and unprotected things; the mode, not the adjective, defines the behavior.</li></ol><h3 id="relation-to-the-mutation-authority-field" tabindex="-1">Relation to the mutation-authority field <a class="header-anchor" href="#relation-to-the-mutation-authority-field" aria-label="Permalink to &quot;Relation to the mutation-authority field&quot;">​</a></h3><p>Where built-in resources are rows and coexist with system-managed and API-managed rows on the same table, they take a distinct <code>managed_by</code> value (<code>builtin</code>), because their authority (the release) is neither the deployment configuration nor any principal. Where the built-in is enforced through a dedicated type column instead (a sentinel row on a table that otherwise has no authority field), that column plus triggers is the equivalent mechanism, and adding a redundant authority field is unnecessary. Mode 5 rows are not built-in after copying and take ordinary authority values.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../8779742261/README.html">ADR#8779742261: Actor and Authority Taxonomy</a></li><li><a href="https://kubernetes.io/docs/reference/access-authn-authz/rbac/" target="_blank" rel="noreferrer">Kubernetes default roles and auto-reconciliation</a></li><li><a href="https://www.postgresql.org/docs/current/manage-ag-templatedbs.html" target="_blank" rel="noreferrer">PostgreSQL template databases</a></li><li><a href="https://grafana.com/docs/grafana/latest/administration/roles-and-permissions/access-control/" target="_blank" rel="noreferrer">Grafana RBAC: basic and fixed roles</a></li><li><a href="https://developer.okta.com/docs/concepts/policies/" target="_blank" rel="noreferrer">Okta policy concepts (default policies)</a></li><li><a href="https://docs.github.com/en/organizations/managing-organization-settings/managing-default-labels-for-repositories-in-your-organization" target="_blank" rel="noreferrer">GitHub default labels</a></li><li><a href="https://docs.cloud.google.com/iam/docs/roles-overview" target="_blank" rel="noreferrer">GCP predefined roles</a></li><li><a href="https://learn.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure-basics" target="_blank" rel="noreferrer">Azure Policy <code>policyType</code></a></li></ul>',18)])])}const p=t(r,[["render",n]]);export{m as __pageData,p as default};
